        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = float(spy_bar.Close)
        current_spy_sma = float(self.spy_sma.Current.Value)

        spy_crossed_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > current_spy_sma
        )

        spy_crossed_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_sell_reason = float(self.aapl_rsi.Current.Value) > 60.0

        # Evaluate sells before buys.
        if self.Portfolio[self.spy].Quantity > 0 and spy_crossed_below:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Strategy A sell"
            )

        if self.Portfolio[self.aapl].Quantity > 0 and aapl_sell_reason:
            self.MarketOrder(
                self.aapl,
                -self.Portfolio[self.aapl].Quantity,
                tag="Strategy B sell"
            )

        if self.Portfolio[self.spy].Quantity == 0 and spy_crossed_above:
            shares = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / spy_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares, tag="Strategy A buy")

        if self.Portfolio[self.aapl].Quantity == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20000.0:
                shares = int(20000.0 / float(aapl_bar.Close))
                if shares > 0:
                    self.MarketOrder(self.aapl, shares, tag="Strategy B buy")

        self.previous_spy_close = spy_close
        self.previous_spy_sma = current_spy_sma

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars and self.spy_sma.IsReady:
            self.previous_spy_close = float(data.Bars[self.spy].Close)
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

        if self.aapl in data.Bars:
            close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = close
