                if tag.startswith("B_") and order_event.Status != OrderStatus.PartiallyFilled:
                    self.strategy_b_pending = False
            return

        tag = order_event.Tag or ""
        filled_quantity = int(order_event.FillQuantity)

        if tag == "A_BUY":
            self.strategy_a_lot += filled_quantity
            self.strategy_a_pending = False
        elif tag == "A_SELL":
            self.strategy_a_lot += filled_quantity
            if self.strategy_a_lot <= 0:
                self.strategy_a_lot = 0
                self.strategy_a_pending = False
        elif tag == "B_BUY":
            self.strategy_b_lot += filled_quantity
            self.strategy_b_pending = False
        elif tag == "B_SELL":
            self.strategy_b_lot += filled_quantity
            if self.strategy_b_lot <= 0:
                self.strategy_b_lot = 0
                self.strategy_b_pending = False
