class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_close = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {}

    def OnData(self, data):
        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_close = float(data.Bars[spy].Close)
        aapl_close = float(data.Bars[aapl].Close)

        previous_spy_close = self.previous_close.get(spy)
        previous_aapl_close = self.previous_close.get(aapl)

        spy_crossed_above = False
        spy_crossed_below = False

        if (
            previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.spy_sma.IsReady
        ):
            spy_crossed_above = (
                previous_spy_close <= float(self.previous_spy_sma)
                and spy_close > float(self.spy_sma.Current.Value)
            )
            spy_crossed_below = (
                previous_spy_close >= float(self.previous_spy_sma)
                and spy_close < float(self.spy_sma.Current.Value)
            )

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Evaluate sells before buys.
        if self.lots["A"] > 0 and spy_crossed_below:
            self._liquidate_lot("A", spy)

        if (
            self.lots["B"] > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._liquidate_lot("B", aapl)

        if (
            self.lots["A"] == 0
            and "A" not in self.pending_orders
            and self.spy_sma.IsReady
            and spy_crossed_above
        ):
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if quantity > 0:
                self._submit_order("A", spy, quantity, "buy")

        if (
            self.lots["B"] == 0
            and "B" not in self.pending_orders
            and self.aapl_red_streak >= 3
            and self.aapl_rsi.IsReady
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self._submit_order("B", aapl, quantity, "buy")

        self.previous_close[spy] = spy_close
        self.previous_close[aapl] = aapl_close

        if self.spy_sma.IsReady:
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

    def _submit_order(self, strategy, symbol, quantity, action):
        ticket = self.MarketOrder(symbol, quantity if action == "buy" else -quantity)
        self.pending_orders[strategy] = ticket.OrderId
        self.pending_orders[ticket.OrderId] = (strategy, action)

    def _liquidate_lot(self, strategy, symbol):
        quantity = self.lots[strategy]
        if quantity > 0:
            self._submit_order(strategy, symbol, quantity, "sell")

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        strategy, action = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)

        if action == "buy":
            self.lots[strategy] += fill_quantity
        else:
            self.lots[strategy] += fill_quantity

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.pending_orders.pop(order_id, None)
            if self.pending_orders.get(strategy) == order_id:
                self.pending_orders.pop(strategy, None)
